SELECT

FROM system_server_log


        AND system_server_log_server_id = #{serverId}


        AND system_server_log_filter_type = #{filterType}


        AND system_server_log_process_status = #{processStatus}


        AND system_server_log_client_ip = #{clientIp}


        AND system_server_log_access_time >= #{startTime}


        AND system_server_log_access_time <= #{endTime}


ORDER BY system_server_log_access_time DESC

